// Parallel Bible corpus (Bibel Simalungun 2007 ↔ Alkitab Terjemahan Baru) and the
// statistical word lexicon learned from it. Generated by scripts/build-bible-corpus.mjs
// into public/data/ and loaded lazily, so it works on static hosts like GitHub Pages.

/** [bookIndex, chapter, verse, simalungun, indonesian] */
export type ParallelVerse = [number, number, number, string, string];
/** [word, verseFrequency, [[indonesian, score], ...], exampleVerseIndexes] */
export type LexiconRow = [string, number, [string, number][], number[]];

export interface BibleCorpus {
  source: string;
  /** [code, simalungunName, indonesianName] */
  books: [string, string, string][];
  verses: ParallelVerse[];
  lexicon: LexiconRow[];
  bySmgWord: Map<string, LexiconRow>;
  /** indonesian word -> simalungun rows whose candidates include it, best first */
  byIdnWord: Map<string, { row: LexiconRow; score: number }[]>;
}

export interface WordLookup {
  query: string;
  matchedWord: string;
  frequency: number;
  candidates: { indonesian: string; score: number }[];
  examples: ParallelVerse[];
  confidence: 'tinggi' | 'sedang' | 'rendah';
}

let loading: Promise<BibleCorpus> | null = null;
let loaded: BibleCorpus | null = null;

/** The corpus if it has finished loading, for synchronous callers like the offline translator. */
export function getLoadedBibleCorpus(): BibleCorpus | null {
  return loaded;
}

export function loadBibleCorpus(): Promise<BibleCorpus> {
  if (!loading) {
    loading = Promise.all([
      fetch('data/bible-parallel.json').then((r) => r.json()),
      fetch('data/smg-lexicon.json').then((r) => r.json()),
    ])
      .then(([bible, lex]) => (loaded = buildIndexes(bible, lex.lexicon)))
      .catch((err) => {
        loading = null; // allow retry
        throw err;
      });
  }
  return loading;
}

function buildIndexes(
  bible: { source: string; books: [string, string, string][]; verses: ParallelVerse[] },
  lexicon: LexiconRow[]
): BibleCorpus {
  const bySmgWord = new Map<string, LexiconRow>();
  const byIdnWord = new Map<string, { row: LexiconRow; score: number }[]>();
  for (const row of lexicon) {
    bySmgWord.set(row[0], row);
    for (const [idn, score] of row[2]) {
      // weight by frequency so common words win over rare ones with similar scores
      const weighted = score * Math.log2(row[1] + 1);
      const list = byIdnWord.get(idn) || [];
      list.push({ row, score: weighted });
      byIdnWord.set(idn, list);
    }
  }
  for (const list of byIdnWord.values()) list.sort((a, b) => b.score - a.score);
  return { ...bible, lexicon, bySmgWord, byIdnWord };
}

export function verseReference(corpus: BibleCorpus, v: ParallelVerse): string {
  const [, smgName, idnName] = corpus.books[v[0]];
  const cv = `${v[1]}:${v[2]}`;
  return smgName.toLowerCase() === idnName.toLowerCase()
    ? `${idnName} ${cv}`
    : `${idnName} ${cv} (${smgName} ${cv})`;
}

function confidenceOf(freq: number, topScore: number): WordLookup['confidence'] {
  if (freq >= 10 && topScore >= 0.4) return 'tinggi';
  if (freq >= 3 && topScore >= 0.15) return 'sedang';
  return 'rendah';
}

const normalizeWord = (w: string) =>
  w
    .toLowerCase()
    .replace(/[^a-zà-ÿ-]/g, '')
    .replace(/^-+|-+$/g, '');

// Simalungun possessive suffixes: tanohni, uhurmu, bapanami, ...
const SMG_SUFFIXES = ['nasiam', 'nima', 'nami', 'nasida', 'ni', 'mu', 'hu', 'ta', 'kon'];

/** Simalungun word → Indonesian meanings learned from the parallel Bible. */
export function lookupSimalungunWord(corpus: BibleCorpus, rawWord: string): WordLookup | null {
  const word = normalizeWord(rawWord);
  if (!word) return null;
  let row = corpus.bySmgWord.get(word);
  if (!row) {
    for (const suffix of SMG_SUFFIXES) {
      if (word.length > suffix.length + 2 && word.endsWith(suffix)) {
        row = corpus.bySmgWord.get(word.slice(0, -suffix.length));
        if (row) break;
      }
    }
  }
  if (!row) return null;
  const candidates = row[2].map(([indonesian, score]) => ({ indonesian, score }));
  return {
    query: rawWord,
    matchedWord: row[0],
    frequency: row[1],
    candidates,
    examples: row[3].map((i) => corpus.verses[i]),
    confidence: confidenceOf(row[1], candidates[0]?.score ?? 0),
  };
}

const IDN_SUFFIXES = ['lah', 'kah', 'nya', 'mu', 'ku'];

/** Indonesian word → Simalungun words that translate to it. */
export function lookupIndonesianWord(
  corpus: BibleCorpus,
  rawWord: string,
  max = 5
): { simalungun: string; frequency: number; score: number }[] {
  const word = normalizeWord(rawWord);
  let list = corpus.byIdnWord.get(word);
  if (!list) {
    for (const suffix of IDN_SUFFIXES) {
      if (word.length > suffix.length + 2 && word.endsWith(suffix)) {
        list = corpus.byIdnWord.get(word.slice(0, -suffix.length));
        if (list) break;
      }
    }
  }
  return (list || []).slice(0, max).map(({ row, score }) => ({
    simalungun: row[0],
    frequency: row[1],
    score,
  }));
}

/** Finds a verse by reference in either language: "Yohanes 3:16", "1 Musa 1:1", "mazmur 23 1". */
export function findVerseByReference(corpus: BibleCorpus, query: string): ParallelVerse[] | null {
  const m = query
    .trim()
    .toLowerCase()
    .match(/^(\d?\s?[a-z][a-z\s-]*?)\s*(\d+)(?:\s*[:.,\s]\s*(\d+)(?:\s*[-–]\s*(\d+))?)?$/);
  if (!m) return null;
  const name = m[1].replace(/\s+/g, ' ').trim();
  const compact = name.replace(/\s/g, '');
  const bookIndex = corpus.books.findIndex(([code, smg, idn]) =>
    [smg, idn, code].some((n) => {
      const ln = n.toLowerCase();
      return ln === name || ln.replace(/\s/g, '') === compact || (compact.length >= 3 && ln.replace(/\s/g, '').startsWith(compact));
    })
  );
  if (bookIndex < 0) return null;
  const chapter = Number(m[2]);
  const from = m[3] ? Number(m[3]) : 1;
  const to = m[4] ? Number(m[4]) : m[3] ? from : 999;
  const hits = corpus.verses.filter(
    (v) => v[0] === bookIndex && v[1] === chapter && v[2] >= from && v[2] <= to
  );
  return hits.length ? hits : null;
}

/** Full-text search over both languages. Whole-word matches rank first, short verses next. */
export function searchVerses(corpus: BibleCorpus, query: string, limit = 20): ParallelVerse[] {
  const byRef = findVerseByReference(corpus, query);
  if (byRef) return byRef.slice(0, limit);
  const q = query.trim().toLowerCase();
  if (q.length < 2) return [];
  const escaped = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const wholeWord = new RegExp(`(^|[^a-zà-ÿ])${escaped}($|[^a-zà-ÿ])`, 'i');
  const hits: { v: ParallelVerse; rank: number }[] = [];
  for (const v of corpus.verses) {
    const smg = v[3].toLowerCase();
    const idn = v[4].toLowerCase();
    if (!smg.includes(q) && !idn.includes(q)) continue;
    const whole = wholeWord.test(smg) || wholeWord.test(idn);
    hits.push({ v, rank: (whole ? 0 : 10000) + v[3].length });
  }
  return hits
    .sort((a, b) => a.rank - b.rank)
    .slice(0, limit)
    .map((h) => h.v);
}

// Emphasis particles and the possessive linker "ni" have no Indonesian word of their own.
const SMG_SKIP = new Set(['ma', 'do', 'pe', 'ni']);
// Common words whose statistical meaning is misleading on its own.
const SMG_FIXED: Record<string, string> = {
  au: 'aku',
  ahu: 'aku',
  sai: 'kiranya',
  atei: 'hati',
  seng: 'tidak',
  lang: 'tidak',
  bangku: 'kepadaku',
  in: 'itu',
  bai: 'kepada',
  bamu: 'kepada-Mu',
  banta: 'kepada kita',
};
const CLITICS: Record<string, string> = { mu: 'mu', ni: 'nya', ku: 'ku', hu: 'ku' };
const PRONOUN_SUFFIXES: [string, string][] = [
  ['nami', ' kami'],
  ['nima', ' kalian'],
  ['ta', ' kita'],
  ['mu', 'mu'],
  ['hu', 'ku'],
  ['ku', 'ku'],
];

function glossWord(corpus: BibleCorpus, word: string): string | null {
  if (SMG_FIXED[word]) return SMG_FIXED[word];
  const hit = lookupSimalungunWord(corpus, word);
  const top = hit?.candidates[0]?.indonesian;
  if (hit && top && hit.confidence !== 'rendah') return top;
  // Fused possessive: "tuhanta" → "tuhan kita", "uhurhu" → "hatiku".
  for (const [suf, idn] of PRONOUN_SUFFIXES) {
    if (word.length > suf.length + 2 && word.endsWith(suf)) {
      const stem = glossWord(corpus, word.slice(0, -suf.length));
      if (stem) return stem + idn;
    }
  }
  return top ? `${top}?` : null; // a weak guess is marked with "?"
}

/**
 * Word-by-word Indonesian gloss of a Simalungun line using the corpus lexicon.
 * Weak guesses end with "?", unknown words stay in [brackets], so the reader can see the gaps.
 */
export function glossSimalungunLine(corpus: BibleCorpus, line: string): string {
  return line
    .split(/\s+/)
    .map((token) => {
      const word = normalizeWord(token);
      const punct = token.match(/[,.;:!?]+$/)?.[0] ?? '';
      if (!word) return token;
      if (SMG_SKIP.has(word)) return punct;
      // "goran-Mu" → "nama-Mu", "atei-Ni" → "hati-Nya"
      const clitic = word.match(/^(.+)-(mu|ni|ku|hu)$/);
      if (clitic) {
        const stem = glossWord(corpus, clitic[1]);
        const capital = /-[A-Z]/.test(token);
        const suffix = CLITICS[clitic[2]];
        if (stem) return `${stem.replace(/\?$/, '')}-${capital ? suffix[0].toUpperCase() + suffix.slice(1) : suffix}${punct}`;
      }
      return (glossWord(corpus, word) ?? `[${word}]`) + punct;
    })
    .filter(Boolean)
    .join(' ')
    .replace(/\s+([,.;:!?])/g, '$1');
}

// --- Matching free text (e.g. a line read from a photo) to a verse -----------------

interface WordIndex {
  verses: Map<string, number[]>; // word -> verse indexes
  idf: (word: string) => number;
}
const wordIndexes = new WeakMap<BibleCorpus, { smg: WordIndex; idn: WordIndex }>();

const matchTokens = (text: string) =>
  text
    .toLowerCase()
    .replace(/[^a-zà-ÿ\s-]/g, ' ')
    .split(/[\s-]+/)
    .filter((w) => w.length >= 2);

function buildWordIndex(corpus: BibleCorpus, field: 3 | 4): WordIndex {
  const verses = new Map<string, number[]>();
  corpus.verses.forEach((v, i) => {
    for (const w of new Set(matchTokens(v[field]))) {
      const list = verses.get(w);
      if (list) list.push(i);
      else verses.set(w, [i]);
    }
  });
  const total = corpus.verses.length;
  return { verses, idf: (w) => Math.log(total / (1 + (verses.get(w)?.length ?? 0))) };
}

function indexesFor(corpus: BibleCorpus) {
  let idx = wordIndexes.get(corpus);
  if (!idx) {
    idx = { smg: buildWordIndex(corpus, 3), idn: buildWordIndex(corpus, 4) };
    wordIndexes.set(corpus, idx);
  }
  return idx;
}

export interface VerseMatch {
  verse: ParallelVerse;
  index: number;
  lang: 'smg' | 'idn';
  /** share of the text's (rarity-weighted) words found in the verse, 0–1 */
  score: number;
}

/**
 * Finds the verse a piece of text comes from, in either language. OCR mistakes are
 * tolerated because only most of the words need to match. Returns null below `minScore`.
 */
export function matchVerse(corpus: BibleCorpus, text: string, minScore = 0.6): VerseMatch | null {
  const words = [...new Set(matchTokens(text))];
  if (words.length < 3) return null;
  const idx = indexesFor(corpus);
  let best: VerseMatch | null = null;
  for (const lang of ['smg', 'idn'] as const) {
    const index = idx[lang];
    const known = words.filter((w) => index.verses.has(w));
    if (known.length < 3) continue;
    // Candidates come from the rarest words, which point to only a few verses.
    const rare = [...known].sort((a, b) => index.idf(b) - index.idf(a)).slice(0, 3);
    const candidates = new Set(rare.flatMap((w) => index.verses.get(w) ?? []));
    const totalWeight = words.reduce((s, w) => s + Math.max(index.idf(w), 0.5), 0);
    for (const vi of candidates) {
      const verseWords = new Set(matchTokens(corpus.verses[vi][lang === 'smg' ? 3 : 4]));
      const hit = words.reduce((s, w) => s + (verseWords.has(w) ? Math.max(index.idf(w), 0.5) : 0), 0);
      const score = hit / totalWeight;
      if (!best || score > best.score) best = { verse: corpus.verses[vi], index: vi, lang, score };
    }
  }
  if (!best || best.score < minScore) return null;
  // Common words ("holong ni Naibata do ...") occur in many verses; a real quote also keeps
  // the word order, so most of its word pairs must appear in the verse as well.
  const pairs = (tokens: string[]) => tokens.slice(1).map((w, i) => `${tokens[i]} ${w}`);
  const textPairs = pairs(matchTokens(text));
  const versePairs = new Set(pairs(matchTokens(best.verse[best.lang === 'smg' ? 3 : 4])));
  const ordered = textPairs.filter((p) => versePairs.has(p)).length / Math.max(1, textPairs.length);
  return ordered >= 0.5 ? best : null;
}

/**
 * Share (0–1) of the text's words found in one given verse. Used to keep a line with
 * its neighbours: a phrase that occurs in several verses belongs to the verse around it.
 */
export function scoreTextInVerse(corpus: BibleCorpus, text: string, index: number, lang: 'smg' | 'idn'): number {
  const words = [...new Set(matchTokens(text))];
  if (words.length === 0) return 0;
  const idx = indexesFor(corpus)[lang];
  const verseWords = new Set(matchTokens(corpus.verses[index][lang === 'smg' ? 3 : 4]));
  const total = words.reduce((s, w) => s + Math.max(idx.idf(w), 0.5), 0);
  const hit = words.reduce((s, w) => s + (verseWords.has(w) ? Math.max(idx.idf(w), 0.5) : 0), 0);
  return hit / total;
}

/**
 * Assigns lines of a page to verses using their neighbours as context, so short lines
 * ("banggal in.") and phrases repeated elsewhere in the Bible stay with the verse they belong to.
 */
export function matchLinesToVerses(corpus: BibleCorpus, lines: string[]): (VerseMatch | null)[] {
  const result = lines.map((t) => matchVerse(corpus, t));

  // The page's chapter is the one most confidently matched lines agree on.
  const chapterOf = (m: VerseMatch) => `${m.verse[0]}:${m.verse[1]}`;
  const votes = new Map<string, number>();
  for (const m of result) if (m && m.score >= 0.75) votes.set(chapterOf(m), (votes.get(chapterOf(m)) ?? 0) + 1);
  const pageChapter = [...votes].sort((a, b) => b[1] - a[1])[0]?.[0];
  const onPage = (m: VerseMatch | null) => m !== null && chapterOf(m) === pageChapter;

  // A verse runs over consecutive lines, so a line that also fits its neighbour's verse
  // (on this page's chapter) belongs to that verse.
  for (let pass = 0; pass < 2; pass++) {
    for (let i = 0; i < lines.length; i++) {
      for (const j of [i - 1, i + 1]) {
        const neighbour = result[j];
        if (!neighbour || neighbour.index === result[i]?.index || !onPage(neighbour)) continue;
        if (onPage(result[i]) && neighbour.score < 0.75) continue;
        const score = scoreTextInVerse(corpus, lines[i], neighbour.index, neighbour.lang);
        if (score >= 0.75) {
          result[i] = { ...neighbour, score };
          break;
        }
      }
    }
  }
  return result;
}

/** Total number of verses containing the query (for "n ayat ditemukan"). */
export function countVerses(corpus: BibleCorpus, query: string): number {
  const q = query.trim().toLowerCase();
  if (q.length < 2) return 0;
  let n = 0;
  for (const v of corpus.verses) if (v[3].toLowerCase().includes(q) || v[4].toLowerCase().includes(q)) n++;
  return n;
}
